//! Response types for node graph UI events.
//!
//! Defines the custom events that can be generated by node interactions.

use egui_node_graph2::UserResponseTrait;

/// What a learn walking a group (#481) is asked to do.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum WalkAction {
    /// Start one on the group whose node this is.
    Start(egui_node_graph2::NodeId),
    /// Leave the module waiting as it is, and go on to the next.
    Skip,
    /// Stop, keeping what was learned.
    Stop,
}

/// Custom responses generated by node graph interactions.
///
/// These events are collected during UI drawing and processed
/// to trigger actions like syncing with the audio engine.
#[derive(Clone, Debug, PartialEq)]
pub enum SynthResponse {
    /// A parameter value was changed.
    ParameterChanged {
        node_id: egui_node_graph2::NodeId,
        param_name: String,
        value: f32,
    },
    /// Parameters set together by one gesture on a node's display, such as
    /// a click on the Trigger Sequencer's grid. Undo takes them back as one
    /// step of their own, named `label`, however quickly the next follows.
    EditParameters {
        node_id: egui_node_graph2::NodeId,
        label: String,
        changes: Vec<(String, f32)>,
    },
    /// Names given to things on a node that aren't parameters, such as an
    /// Arranger's sections: key to text, with empty text taking the name
    /// away. Undo takes them back as a step named `label`, together with
    /// any parameters edited in the same frame.
    SetLabels {
        node_id: egui_node_graph2::NodeId,
        label: String,
        labels: Vec<(String, String)>,
    },
    /// A parameter played rather than edited, like a Looper's footswitch
    /// pressed on the node: it reaches the engine at once, as a MIDI
    /// controller's would, and isn't an undo step.
    PlayParameter {
        node_id: egui_node_graph2::NodeId,
        param_name: String,
        value: f32,
    },
    /// A chord played on a node's outputs from its face while a hand is
    /// down, or `None` once it lifts: played, like `PlayParameter`, and
    /// never kept or undone.
    Audition {
        node_id: egui_node_graph2::NodeId,
        chord: Option<crate::dsp::Audition>,
    },
    /// A Sampler's file heard from its face, from `from` to `to` (0 to 1
    /// through it), beside the patch: played, never kept or undone.
    CueSample {
        node_id: egui_node_graph2::NodeId,
        from: f32,
        to: f32,
    },
    /// The file being heard from a Sampler's face, stopped.
    StopCue(egui_node_graph2::NodeId),
    /// A node was selected by right-clicking it, so its menu acts on it.
    NodeSelected(egui_node_graph2::NodeId),
    /// A node was deselected.
    NodeDeselected(egui_node_graph2::NodeId),
    /// Request to delete a node.
    DeleteNode(egui_node_graph2::NodeId),
    /// Request to reset a node's parameters to defaults.
    ResetNode(egui_node_graph2::NodeId),
    /// Request to duplicate a node, with the cables between it and any
    /// other selected nodes.
    DuplicateNode(egui_node_graph2::NodeId),
    /// Request to copy a node to the clipboard.
    CopyNode(egui_node_graph2::NodeId),
    /// Request to bypass a node, or bring it back.
    ToggleBypass(egui_node_graph2::NodeId),
    /// Request to start MIDI Learn mode for a parameter, or a Scenes pad.
    MidiLearnStart {
        engine_node_id: u64,
        param_index: usize,
        param_name: String,
        min_value: f32,
        max_value: f32,
        /// What kind of control it is: what a CC or a note does to it.
        control: crate::persistence::MidiControl,
        /// The Scenes pad (0-7) to recall, in place of a parameter.
        scene: Option<u8>,
        /// Where in the module to write what's heard, in place of mapping
        /// it: a Control learning its fader (see
        /// [`crate::app::module_learn`]). Boxed, as few learns have one.
        into: Option<Box<crate::app::module_learn::ModuleLearn>>,
    },
    /// Request to clear the MIDI mapping of a parameter, or a Scenes pad.
    MidiLearnClear {
        engine_node_id: u64,
        param_index: usize,
        scene: Option<u8>,
    },
    /// Request to restyle the MIDI mapping of a parameter: an endless
    /// encoder or not, picking up or jumping, and which way up.
    MidiStyle {
        engine_node_id: u64,
        param_index: usize,
        scene: Option<u8>,
        style: super::MidiStyle,
    },
    /// Request to leave MIDI Learn mode without mapping anything.
    MidiLearnCancel,
    /// Learn a group's Pads in order, one hit each (#481): start, skip the
    /// one waiting, or stop.
    LearnWalk(WalkAction),
    /// In the plugin, map the host's macro `slot` (0-7) to a parameter, in
    /// place of any CC or macro it had.
    MapToMacro {
        engine_node_id: u64,
        param_index: usize,
        param_name: String,
        min_value: f32,
        max_value: f32,
        slot: u8,
    },
    /// Show a module's knob on the faces of the groups around it, `levels`
    /// groups up (0 takes it off them all).
    PinKnob {
        node_id: egui_node_graph2::NodeId,
        param_name: String,
        levels: u8,
    },
    /// Call a pinned control `name` on the groups' faces, or with a blank
    /// name, by its module's own short name again.
    NameFaceControl {
        node_id: egui_node_graph2::NodeId,
        param_name: String,
        name: String,
    },
    /// Show a port on the group it's in as a new jack, unplug it from the
    /// group's jack, or rename, move or take away the jack it is.
    Jack {
        node_id: egui_node_graph2::NodeId,
        side: super::groups::Side,
        port: String,
        edit: super::groups::JackEdit,
    },
    /// Group the selection the node is part of (or just the node).
    GroupNode(egui_node_graph2::NodeId),
    /// Take a group apart onto the level it sits on.
    UngroupNode(egui_node_graph2::NodeId),
    /// Show the inside of a group.
    EnterGroup(egui_node_graph2::NodeId),
    /// Start typing a group's name.
    StartRename(egui_node_graph2::NodeId),
    /// A group's new name, typed.
    RenameGroup {
        node_id: egui_node_graph2::NodeId,
        name: String,
    },
    /// Save a group to My Modules.
    SaveGroup(egui_node_graph2::NodeId),
    /// An FM Voice's file to open or save, or its garden sent as a bank (#448).
    FmVoiceFile {
        node_id: egui_node_graph2::NodeId,
        action: super::fm_voice_face::VoiceFile,
    },
    /// Ask for a file for a Sampler to play.
    OpenSample(egui_node_graph2::NodeId),
    /// Place a new Sampler beside a node, patched from `source`, and record:
    /// `bars` long from the next bar line, or until Rec again if 0.
    RecordInto {
        node_id: egui_node_graph2::NodeId,
        source: super::resample::Source,
        bars: u32,
    },
    /// A scene stored, recalled or cleared from a Scenes module's pads, by
    /// slot. Each is an undo step.
    Scene {
        node_id: egui_node_graph2::NodeId,
        slot: usize,
        action: SceneAction,
    },
    /// A Sampler's slice markers, moved, added or taken away by hand: the
    /// whole list, kept on the node. Undo takes it back as a step named `label`.
    SetSliceMarkers {
        node_id: egui_node_graph2::NodeId,
        label: String,
        markers: crate::dsp::onsets::HandMarkers,
    },
    /// Trim or normalize a Sampler's file, into a new file beside the
    /// patch: a step undo takes back.
    TidySample {
        node_id: egui_node_graph2::NodeId,
        tidy: Tidy,
    },
    /// Save a copy of a Sampler's file kept only in the browser's tab (a
    /// take recorded there), as a download.
    DownloadSample(egui_node_graph2::NodeId),
    /// Send every knob of an Instrument to its hardware again (#442), so
    /// the device comes back to what the patch says.
    SendAll(egui_node_graph2::NodeId),
}

/// What a Sampler's face can do to its file.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Tidy {
    /// Cut it to its sound.
    Trim,
    /// Set its level.
    Normalize(crate::dsp::tidy::Level),
}

impl SynthResponse {
    /// Create a parameter changed response.
    pub fn parameter_changed(
        node_id: egui_node_graph2::NodeId,
        param_name: impl Into<String>,
        value: f32,
    ) -> Self {
        Self::ParameterChanged {
            node_id,
            param_name: param_name.into(),
            value,
        }
    }

    /// Create a node selected response.
    pub fn node_selected(node_id: egui_node_graph2::NodeId) -> Self {
        Self::NodeSelected(node_id)
    }

    /// Create a node deselected response.
    pub fn node_deselected(node_id: egui_node_graph2::NodeId) -> Self {
        Self::NodeDeselected(node_id)
    }

    /// Create a delete node response.
    pub fn delete_node(node_id: egui_node_graph2::NodeId) -> Self {
        Self::DeleteNode(node_id)
    }

    /// Create a reset node response.
    pub fn reset_node(node_id: egui_node_graph2::NodeId) -> Self {
        Self::ResetNode(node_id)
    }

    /// Create a MIDI learn start response for a parameter.
    pub fn midi_learn_start(
        engine_node_id: u64,
        param_index: usize,
        param_name: impl Into<String>,
        min_value: f32,
        max_value: f32,
        control: crate::persistence::MidiControl,
    ) -> Self {
        Self::MidiLearnStart {
            engine_node_id,
            param_index,
            param_name: param_name.into(),
            min_value,
            max_value,
            control,
            scene: None,
            into: None,
        }
    }

    /// Create a MIDI learn clear response for a parameter.
    pub fn midi_learn_clear(engine_node_id: u64, param_index: usize) -> Self {
        Self::MidiLearnClear {
            engine_node_id,
            param_index,
            scene: None,
        }
    }
}

impl UserResponseTrait for SynthResponse {}

#[cfg(test)]
mod tests {
    use super::*;

    /// A real node id, from a node added to a graph
    fn make_node_id() -> egui_node_graph2::NodeId {
        let data = crate::graph::SynthNodeData::new("test.node", "Test", crate::dsp::ModuleCategory::Utility);
        crate::graph::SynthGraph::default().add_node("Test".to_string(), data, |_, _| {})
    }

    #[test]
    fn test_parameter_changed() {
        let node_id = make_node_id();
        let response = SynthResponse::parameter_changed(node_id, "frequency", 440.0);

        match response {
            SynthResponse::ParameterChanged {
                param_name, value, ..
            } => {
                assert_eq!(param_name, "frequency");
                assert!((value - 440.0).abs() < f32::EPSILON);
            }
            _ => panic!("Expected ParameterChanged"),
        }
    }

    #[test]
    fn test_node_selected() {
        let node_id = make_node_id();
        let response = SynthResponse::node_selected(node_id);

        assert!(matches!(response, SynthResponse::NodeSelected(_)));
    }

    #[test]
    fn test_delete_node() {
        let node_id = make_node_id();
        let response = SynthResponse::delete_node(node_id);

        assert!(matches!(response, SynthResponse::DeleteNode(_)));
    }

    #[test]
    fn test_response_clone() {
        let node_id = make_node_id();
        let original = SynthResponse::parameter_changed(node_id, "test", 1.0);
        let cloned = original.clone();

        assert_eq!(original, cloned);
    }
}

/// What a click on a Scenes pad does.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SceneAction {
    /// Keep the knobs as they stand in the slot.
    Store,
    /// Set the knobs to the slot's scene.
    Recall,
    /// Empty the slot.
    Clear,
}
